 3	public final class BellmanFord {
 4	    private static final int INF = 100_000_000;
 5	    private static final int[] NEGATIVE_CYCLE_RESULT = {-1};
 6	
 7	    private BellmanFord() {
 8	    }
 9	
10	    public static int[] bellmanFord(int vertices, int[][] edgeData, int source) {
11	        return shortestPaths(vertices, edgeData, source);
12	    }
13	
14	    public static int[] shortestPaths(int vertices, int[][] edgeData, int source) {
15	        ShortestPathResult result = computeShortestPaths(WeightedGraph.from(vertices, edgeData), source);
16	        if (result.hasNegativeCycle()) {
17	            return NEGATIVE_CYCLE_RESULT.clone();
18	        }
19	        return result.distances();
20	    }
21	
22	    public static ShortestPathResult computeShortestPaths(WeightedGraph graph, int source) {
23	        validateSource(source, graph.vertices());
24	        WeightedEdge[] edges = graph.edgeArray();
25	        int[] distances = initializeDistances(graph.vertices(), source);
26	
27	        for (int pass = 0; pass < graph.vertices() - 1; pass++) {
28	            boolean updated = false;
29	
30	            for (WeightedEdge edge : edges) {
31	                updated |= relax(edge, distances);
32	            }
33	
34	            if (!updated) {
35	                return ShortestPathResult.success(distances);
36	            }
37	        }
38	
39	        if (hasNegativeCycle(edges, distances)) {
40	            return ShortestPathResult.negativeCycle();
41	        }
42	
43	        return ShortestPathResult.success(distances);
44	    }
45	
46	    private static int[] initializeDistances(int vertices, int source) {
47	        int[] distances = new int[vertices];
48	        Arrays.fill(distances, INF);
49	        distances[source] = 0;
50	        return distances;
51	    }
52	
53	    private static boolean relax(WeightedEdge edge, int[] distances) {
54	        if (distances[edge.from()] == INF) {
55	            return false;
56	        }
57	
58	        int candidateDistance = distances[edge.from()] + edge.weight();
59	        if (candidateDistance >= distances[edge.to()]) {
60	            return false;
61	        }
62	
63	        distances[edge.to()] = candidateDistance;
64	        return true;
65	    }
66	
67	    private static boolean hasNegativeCycle(WeightedEdge[] edges, int[] distances) {
68	        for (WeightedEdge edge : edges) {
69	            if (distances[edge.from()] != INF
70	                    && distances[edge.from()] + edge.weight() < distances[edge.to()]) {
71	                return true;
72	            }
73	        }
74	        return false;
75	    }
76	
77	    private static void validateSource(int source, int vertices) {
78	        validateVertex(source, vertices, "source");
79	    }
80	
81	    private static void validateVertex(int vertex, int vertices, String label) {
82	        if (vertex < 0 || vertex >= vertices) {
83	            throw new IllegalArgumentException(label + " must be within the vertex range");
84	        }
85	    }
86	}

